import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadDeeporBeelData(){const e=readFileSync(resolve(__dirname,"../../frontend/deepor-beel-explorer/deepor-beel-data.js"),"utf-8");return new Function(e+"\nreturn { DEEPOR_BEEL_INFO, ECOLOGY_HYDROLOGY, BIRD_SPECIES, MAP_HOTSPOTS, GALLERY_IMAGES };")()}function loadWetlandsLandingData(){let e=readFileSync(resolve(__dirname,"../../frontend/wetlands/wetlands-data.js"),"utf-8");e=e.replace(/export\s+const\s+/g,"const ");return new Function(e+"\nreturn WETLANDS_DATA;")()}describe("Deepor Beel Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadDeeporBeelData()}),describe("DEEPOR_BEEL_INFO metadata",()=>{it("contains correct wetland metadata and status",()=>{expect(e.DEEPOR_BEEL_INFO.id).toBe("deepor-beel-explorer"),expect(e.DEEPOR_BEEL_INFO.name).toContain("Deepor Beel"),expect(e.DEEPOR_BEEL_INFO.ramsarYear).toBe(2002),expect(e.DEEPOR_BEEL_INFO.ramsarSiteNo).toBe(1207),expect(e.DEEPOR_BEEL_INFO.state).toBe("Assam")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.DEEPOR_BEEL_INFO.quickStats)).toBe(!0),expect(e.DEEPOR_BEEL_INFO.quickStats.length).toBe(6)})}),describe("ECOLOGY_HYDROLOGY",()=>{it("contains history, ramsarSite, elephantCorridor, wetlandBirds, fisheries, and biodiversity",()=>{expect(e.ECOLOGY_HYDROLOGY.history).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.ramsarSite).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.elephantCorridor).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.wetlandBirds).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.fisheries).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.biodiversity).toBeDefined()})}),describe("BIRD_SPECIES catalog",()=>{it("is a non-empty array of bird species",()=>{expect(Array.isArray(e.BIRD_SPECIES)).toBe(!0),expect(e.BIRD_SPECIES.length).toBeGreaterThanOrEqual(4)}),it("includes Greater Adjutant (Hargila)",()=>{const t=e.BIRD_SPECIES.find(e=>"greater-adjutant"===e.id);expect(t).toBeDefined()})}),describe("Landing Page Integration",()=>{it("is integrated in WETLANDS_DATA landing page dataset",()=>{const e=loadWetlandsLandingData().wetlands.find(e=>"deepor-beel"===e.id);expect(e).toBeDefined(),expect(e.exploreUrl).toBe("../deepor-beel-explorer/index.html")})})});